-- relationships kept in columns of ms.users: audited when they change; the feed hears of every row
CREATE FUNCTION authz_int."user__col_audit_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('user', ARRAY(SELECT n."id"::text FROM new_rows n), 'insert');
  RETURN NULL;
END $f$;

-- @object trigger "authz_user_col_audit_ins" ON "ms"."users"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"ms"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_ins" AFTER INSERT ON "ms"."users" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_ins"()';
  ELSE
    RAISE NOTICE '"ms"."users" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

CREATE FUNCTION authz_int."user__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('user', ARRAY(SELECT n."id"::text FROM new_rows n UNION SELECT o."id"::text FROM old_rows o), 'update');
  RETURN NULL;
END $f$;

-- @object trigger "authz_user_col_audit_upd" ON "ms"."users"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"ms"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_upd" AFTER UPDATE ON "ms"."users" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_upd"()';
  ELSE
    RAISE NOTICE '"ms"."users" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

CREATE FUNCTION authz_int."user__col_audit_del"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
