    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_del" AFTER DELETE ON "ms"."users" REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_del"()';
