CREATE FUNCTION authz_int."user__col_audit_trunc"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.audit('truncate', 'user', NULL, NULL, NULL, NULL, NULL, jsonb_build_object('table', 'ms.users'));
    PERFORM authz_int.changed('user', ARRAY['*'], 'truncate');
  RETURN NULL;
END $f$;

-- @object trigger "authz_user_col_audit_trunc" ON "ms"."users"
DO $tr$ BEGIN
