    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_trunc" AFTER TRUNCATE ON "ms"."users" FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_trunc"()';
  ELSE
    RAISE NOTICE '"ms"."users" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."user__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."id" IS DISTINCT FROM OLD."id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', NEW."id"::text, 'self', NEW."id"::text, jsonb_build_object('column', 'id', 'was', OLD."id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;

-- @object trigger "authz_user_col_audit_row" ON "ms"."users"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"ms"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_row" AFTER UPDATE ON "ms"."users" FOR EACH ROW WHEN (OLD."id" IS DISTINCT FROM NEW."id") EXECUTE FUNCTION authz_int."user__col_audit_row"()';
  ELSE
    RAISE NOTICE '"ms"."users" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

-- user.self (line 8)
CREATE VIEW authz_int."user__self" AS
  SELECT r."id" AS id FROM "ms"."users" r WHERE r."id" = (SELECT authz.uid());

CREATE VIEW authz_gen."user__self" WITH (security_barrier) AS SELECT id FROM authz_int."user__self";

-- user.edit (line 10): self
CREATE OR REPLACE VIEW authz_int."user__edit" AS
  SELECT id FROM authz_int."user__self";

-- chat.setup (line 34): creator and {not exists (select 1 from ms.members m where m.chat_id = this.id)}
CREATE OR REPLACE VIEW authz_int."chat__setup" AS
  SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = r.id)), false);

-- chat.add_members (line 36): manage or setup or (creator and {kind = 'direct'} and {(select count(*) from ms.members m where m.chat_id = this.id) < 2})
CREATE OR REPLACE VIEW authz_int."chat__add_members" AS
  (SELECT id FROM authz_int."chat__manage")
  UNION ALL
  (SELECT id FROM authz_int."chat__setup")
  UNION ALL
  (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = r.id) < 2), false));

