CREATE FUNCTION authz_gen."ms.users:update:items"(p_row "ms"."users") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(coalesce("users"."id" = (SELECT authz.uid()), false), false),
    coalesce((SELECT authz_int.scope_cmd('ms.users', 'update')), false),
    coalesce(true, false),
    coalesce(coalesce("users"."id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "users";
END;

