  USING (((SELECT authz_int.scope_cmd('ms.users', 'update')) AND coalesce("users"."id" = (SELECT authz.uid()), false)))
  WITH CHECK (((SELECT authz_int.scope_cmd('ms.users', 'update')) AND coalesce("users"."id" = (SELECT authz.uid()), false))
    OR authz_gen."ms.users:update:refuse"(ROW("users".*)::"ms"."users"));
COMMENT ON POLICY "authz_update" ON "ms"."users" IS 'authzc';

CREATE FUNCTION authz_gen."ms.bots:insert:items"(p_row "ms"."bots") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce("bots"."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false)), false),
    coalesce((SELECT authz_int.scope_cmd('ms.bots', 'insert')), false),
    coalesce(coalesce((active), false), false),
    coalesce(coalesce("bots"."owner_id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "bots";
END;

CREATE OR REPLACE FUNCTION authz_gen."ms.bots:insert:why"(p_row "ms"."bots") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.bots:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : owner  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.bots insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on ms.bots'; END IF;
  IF NOT v[3] THEN RETURN NEXT '  no   the row fails the bot type''s where {active}'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'owner';
END $f$;

